cd /workspace && node -e "
const XLSX = require('xlsx');

// Create a new workbook and a sheet named 'Travel'
const wb = XLSX.utils.book_new();
const ws = XLSX.utils.aoa_to_sheet([]);

// Write value 129 at row 43, column 7 (G43)
XLSX.utils.sheet_add_aoa(ws, [[129]], { origin: 'G43' });

// Set the sheet range to include the cell
ws['!ref'] = 'A1:G43';

XLSX.utils.book_append_sheet(wb, ws, 'Travel');
XLSX.writeFile(wb, 'data/travel_expenses.xlsx');

// Verify
const wb2 = XLSX.readFile('data/travel_expenses.xlsx');
const ws2 = wb2.Sheets['Travel'];
const cell = ws2['G43'];
console.log('Sheet:', wb2.SheetNames);
console.log('G43 (row 43, col 7):', cell.v);
"
